const coreGuard=spawnSync(process.execPath,['--import','tsx','--input-type=module','-e',"import {recognizeMilestoneRevenue} from './lib/finance-revenue.ts';try{await recognizeMilestoneRevenue(null,null,'project','gate');process.exitCode=1;}catch(error){if(error.code!=='PROJECTS_DEFERRED')throw error;}"],{env:{...process.env,NEXT_PUBLIC_ERP_MODULE_PROFILE:'core'},encoding:'utf8'});
assert.equal(coreGuard.status,0,coreGuard.stderr);
const client=createClient({url:':memory:'}),db=drizzle(client,{schema});
const owner:Access={id:'owner',name:'Owner',email:'owner@example.com',role:'Owner',companies:['Hagadol','WMK']};
const finance:Access={...owner,id:'finance',role:'Finance',email:'finance@example.com',companies:['Hagadol']};
const sales:Access={...owner,role:'Sales'};
let passed=1;const check=(value:unknown,label:string)=>{assert.ok(value,label);passed++;};
async function rejects(task:Promise<unknown>,code:string){await assert.rejects(task,cause=>cause instanceof FinanceWorkflowError&&cause.code===code);passed++;}
const row=(id:string,extra:Partial<ImportRow>={}):ImportRow=>importRow({id:'1:'+id+':G',source_sheet:'Sheet',source_row:Number(id),source_cell:'G'+id,date:day().replaceAll('-','/'),period:day().slice(0,7).replace('-','/'),date_basis:'Source date',company:'Hagadol',company_original:'Hagadol',kind:'Cash out',description:'Expense '+id,category:'Operations',amount_UGX:100,currency_basis:'UGX',review:'',posting_status:'Review only',possible_duplicates:'',...extra});
async function stage(rows:ImportRow[],tag=crypto.randomUUID()){
 const hash=await fingerprint(tag),id='fi_'+hash,manifestHash=await rowManifest(await Promise.all(rows.map(async r=>({row_key:r.id,row_hash:await fingerprint(r)}))));
 await db.insert(schema.financeImportBatches).values({id,sourceHash:hash,filename:'Fixture.xlsx',expectedRows:rows.length,manifestHash,status:'Review',created:new Date().toISOString(),actor:owner.email});
 for(const r of rows)await db.insert(schema.financeImportRows).values({batchId:id,rowKey:r.id,company:r.company,sourceSheet:r.source_sheet,sourceCell:r.source_cell,payload:JSON.stringify(r),rowHash:await fingerprint(r)});
 return id;
}
async function execute(input:Parameters<typeof buildPlan>[0]){
 return db.transaction(async tx=>{const state=await readFinanceState(tx,owner.companies),plan=buildPlan({...input,actor:owner.email,requestId:crypto.randomUUID()},state);await persistFinancePlan(tx,plan,owner.email);return plan;});
}
const scalar=async(table:typeof schema.journal|typeof schema.records|typeof schema.audit|typeof schema.operations)=>(await db.select({n:sql<number>`count(*)`}).from(table))[0].n;
try{
 for(const file of (await readdir('drizzle')).filter(file=>file.endsWith('.sql')).sort())await client.batch((await readFile('drizzle/'+file,'utf8')).split('--> statement-breakpoint').map(query=>query.trim()).filter(Boolean),'write');
 const source=row('2'),importId=await stage([source]);
 const decisions:ImportDecision[]=[{rowId:source.id,action:'post',posting:{type:'expense',account:'Bank',expenseAccount:'Operating expenses'}}];
 const prepared=await prepareImportPosting(db,finance,importId,decisions);
 check(await scalar(schema.journal)===0&&await scalar(schema.records)===0,'Preparing a batch never creates business records or journal lines');
 await rejects(approveAndPostImport(db,sales,importId,{confirmed:true,reviewHash:prepared.reviewHash,note:'Approved'}),'FINANCE_ACCESS_DENIED');
 await rejects(approveAndPostImport(db,finance,importId,{confirmed:false as true,reviewHash:prepared.reviewHash,note:'Approved'}),'SIGN_OFF_REQUIRED');
 await rejects(approveAndPostImport(db,finance,importId,{confirmed:true,reviewHash:'a'.repeat(64),note:'Approved'}),'REVIEW_CHANGED');
 const posted=await approveAndPostImport(db,finance,importId,{confirmed:true,reviewHash:prepared.reviewHash,note:'Reviewed source and mapping'});
 check(posted.postedRows===1&&await scalar(schema.journal)===2,'Sign off posts through the existing expense engine');
 const retry=await approveAndPostImport(db,finance,importId,{confirmed:true,reviewHash:prepared.reviewHash,note:'Retry'});
 check(JSON.stringify(retry)===JSON.stringify(posted)&&await scalar(schema.journal)===2,'Approval retries do not duplicate records or entries');
 const [approval]=await db.select().from(schema.financeImportReviews).where(eq(schema.financeImportReviews.importId,importId));
 check(approval.approvedBy===finance.email&&approval.status==='Posted'&&!!approval.approvedAt,'Approval identity and sign off are saved');
 const duplicateId=await stage([source]);await rejects(prepareImportPosting(db,finance,duplicateId,decisions),'IMPORT_VALIDATION_FAILED');
 const repeatedA=row('8',{description:'Repeated transaction'}),repeatedB=row('9',{description:'Repeated transaction'}),withinId=await stage([repeatedA,repeatedB]);
 await rejects(prepareImportPosting(db,finance,withinId,[{...decisions[0],rowId:repeatedA.id},{...decisions[0],rowId:repeatedB.id}]),'IMPORT_VALIDATION_FAILED');
 const subtotal=row('10',{description:'Subtotal site costs'}),subtotalId=await stage([subtotal]);
 await rejects(prepareImportPosting(db,finance,subtotalId,[{...decisions[0],rowId:subtotal.id}]),'IMPORT_VALIDATION_FAILED');
 const customer=await execute({action:'create',company:'Hagadol',type:'contact',name:'Settlement customer'});
 const paymentInvoice=await execute({action:'create',company:'Hagadol',type:'invoice',name:'Settlement invoice',partyId:customer.focusId,lines:[{description:'Service',qty:1,rate:1200}]});
 await execute({action:'post',id:paymentInvoice.focusId});
 const paymentRows=[row('20',{kind:'Client receipt',description:'First payment',amount_UGX:200}),row('21',{kind:'Client receipt',description:'Second payment',amount_UGX:300})];
 const paymentId=await stage(paymentRows),target=(await readFinanceState(db,owner.companies)).records.find(record=>record.id===paymentInvoice.focusId)!;
 const paymentDecisions:ImportDecision[]=paymentRows.map(payment=>({rowId:payment.id,action:'post',posting:{type:'settlement',targetId:target.id,expectedVersion:target.version,account:'Bank'}}));
 const paymentReview=await prepareImportPosting(db,finance,paymentId,paymentDecisions);
 const payments=await approveAndPostImport(db,finance,paymentId,{confirmed:true,reviewHash:paymentReview.reviewHash,note:'Both bank receipts matched'});
 check(payments.postedRows===2&&(await readFinanceState(db,owner.companies)).records.find(record=>record.id===target.id)?.paid===500,'Multiple receipts use current target versions inside one atomic batch');
 const flagged=row('3',{possible_duplicates:'Check source row 2'}),flaggedId=await stage([flagged]);
 await rejects(prepareImportPosting(db,finance,flaggedId,[{...decisions[0],rowId:flagged.id}]),'IMPORT_VALIDATION_FAILED');
 const missing=row('4',{date:'',amount_UGX:null,company:'Shared'}),missingId=await stage([missing]);
 await rejects(prepareImportPosting(db,owner,missingId,[{...decisions[0],rowId:missing.id}]),'IMPORT_VALIDATION_FAILED');
 const excluded=await prepareImportPosting(db,owner,missingId,[{rowId:missing.id,action:'exclude',reason:'Awaiting allocation and date evidence'}]);
 const noPosting=await approveAndPostImport(db,owner,missingId,{confirmed:true,reviewHash:excluded.reviewHash,note:'Keep unresolved source outside ledger'});
 check(noPosting.postedRows===0&&noPosting.excludedRows===1,'Unresolved rows can be explicitly excluded without guessing balances');
 const anomaly=row('5',{review:'Confirm original payment account'}),anomalyId=await stage([anomaly]);
 await rejects(prepareImportPosting(db,finance,anomalyId,[{...decisions[0],rowId:anomaly.id}]),'IMPORT_VALIDATION_FAILED');
 const resolved=await prepareImportPosting(db,finance,anomalyId,[{rowId:anomaly.id,action:'post',posting:{type:'expense',account:'Bank',expenseAccount:'Operating expenses'},resolution:'Bank statement reconciled'}]);
 check(!!resolved.reviewHash,'A reviewed anomaly has an explicit resolution');
 const projectPlan=await execute({action:'create',company:'Hagadol',type:'project',name:'Deferred contract',owner:'Engineer'}),projectId=projectPlan.focusId;
 let state=await readFinanceState(db,owner.companies),project=state.records.find(row=>row.id===projectId)!;
 const schedule=await configureRevenueSchedule(db,finance,projectId,{expectedVersion:project.version,contractValue:1000,milestones:[{stage:'Qualification',amount:300},{stage:'Handover',amount:700}],confirmed:true,approvalNote:'Contract performance milestones reviewed, excluding VAT'});
 check(schedule.schedule.approvedBy===finance.email,'Contract schedule is approved by finance');
 const forged=buildPlan({action:'edit',id:projectId,fields:{revenueSchedule:{contractValue:9999}}},await readFinanceState(db,owner.companies));
 check(forged.writes[0].revenueSchedule.contractValue===1000,'Operational project edits cannot forge the finance schedule');
 const inv=await execute({action:'create',company:'Hagadol',type:'invoice',name:'Deferred contract invoice',projectId,revenueRecognition:'Deferred',lines:[{description:'Contract excluding VAT',qty:1,rate:1000}],taxRate:18});
 await execute({action:'post',id:inv.focusId});
 state=await readFinanceState(db,owner.companies);project=state.records.find(row=>row.id===projectId)!;
 check(projectDeferredBalance(state,project)===1000,'Deferred invoice credits the existing liability account excluding VAT');
 check(planningActuals(state,'Hagadol',day(),day(),day()).revenue===1200,'Deferral does not inflate earned revenue or budget actuals');
 const docPlan=await execute({action:'create',company:'Hagadol',type:'document',name:'Lead evidence',projectId,documentKind:'Lead assessment',owner:'Engineer',sourceRef:'TEST',revisionLabel:'1',classification:'Verified Evidence',reviewDue:'2030-01-01'});
 await execute({action:'stage',id:docPlan.focusId,status:'Review'});await execute({action:'stage',id:docPlan.focusId,status:'Verified'});
 state=await readFinanceState(db,owner.companies);project=state.records.find(row=>row.id===projectId)!;const doc=state.records.find(row=>row.id===docPlan.focusId)!;
 const gate=await execute({action:'advance_gate',id:projectId,expectedVersion:project.version,documentIds:[doc.id],documentVersions:{[doc.id]:doc.version},confirmed:true,decision:'Evidence reviewed'});
 check(gate.automaticRevenueIds.length===1&&gate.entries.length===2,'Gate approval automatically creates recognition in the same plan');
 check(gate.entries.some(entry=>entry.account==='Deferred revenue'&&entry.debit===300)&&gate.entries.some(entry=>entry.account==='Sales revenue'&&entry.credit===300),'Recognition debits deferred revenue and credits the existing earned revenue account');
 state=await readFinanceState(db,owner.companies);project=state.records.find(row=>row.id===projectId)!;
 check(financeSnapshot(state,'Hagadol').balances['VAT payable']===-180,'Revenue recognition does not recognise VAT as earned revenue');
 check(projectDeferredBalance(state,project)===700&&planningActuals(state,'Hagadol',day(),day(),day()).revenue===1500,'Project liability and budget earned revenue update correctly');
 const approvedGateId=gate.writes.find(row=>row.type==='project_gate')!.id;
 const idempotent=await recognizeMilestoneRevenue(db,finance,projectId,approvedGateId);
 check(idempotent.alreadyPosted&&idempotent.amount===300&&idempotent.remainingDeferred===700,'Manual helper returns the existing recognition on retry');
 await rejects(configureRevenueSchedule(db,finance,projectId,{expectedVersion:project.version,contractValue:1000,milestones:[{stage:'Handover',amount:1000}],confirmed:true,approvalNote:'Change after completion'}),'SCHEDULE_LOCKED');
 await rejects(recognizeMilestoneRevenue(db,sales,projectId,approvedGateId),'FINANCE_ACCESS_DENIED');
 const restricted={...finance,companies:['WMK']};await rejects(recognizeMilestoneRevenue(db,restricted,projectId,approvedGateId),'GATE_NOT_FOUND');
 await assert.rejects(execute({action:'void',id:inv.focusId,reason:'Would erase earned liability'}));passed++;
 const invalidGate=await execute({action:'create',company:'Hagadol',type:'project',name:'Unfunded contract'});
 state=await readFinanceState(db,owner.companies);const unfunded=state.records.find(row=>row.id===invalidGate.focusId)!;
 await configureRevenueSchedule(db,finance,unfunded.id,{expectedVersion:unfunded.version,contractValue:100,milestones:[{stage:'Qualification',amount:100}],confirmed:true,approvalNote:'Test unearned source requirement'});
 const leadDoc=await execute({action:'create',company:'Hagadol',type:'document',name:'Unfunded lead evidence',projectId:unfunded.id,documentKind:'Lead assessment',owner:'Engineer',sourceRef:'TEST',revisionLabel:'1',classification:'Verified Evidence',reviewDue:'2030-01-01'});
 await execute({action:'stage',id:leadDoc.focusId,status:'Review'});await execute({action:'stage',id:leadDoc.focusId,status:'Verified'});
 state=await readFinanceState(db,owner.companies);const currentUnfunded=state.records.find(row=>row.id===unfunded.id)!,verifiedDoc=state.records.find(row=>row.id===leadDoc.focusId)!;
 await rejects(execute({action:'advance_gate',id:unfunded.id,expectedVersion:currentUnfunded.version,documentIds:[verifiedDoc.id],documentVersions:{[verifiedDoc.id]:verifiedDoc.version},confirmed:true,decision:'Attempt approval without deferred balance'}),'INSUFFICIENT_DEFERRED_REVENUE');
 check(!(await readFinanceState(db,owner.companies)).records.some(row=>row.type==='project_gate'&&row.projectId===unfunded.id),'Failed recognition does not leave an approved gate behind');
 const before=await scalar(schema.journal);const baseline=await scalar(schema.records);
 // First verify approval staleness, then inject a real write failure below.
 const rollbackRow=row('6'),rollbackId=await stage([rollbackRow]);const review=await prepareImportPosting(db,finance,rollbackId,[{...decisions[0],rowId:rollbackRow.id}]);
 await db.update(schema.financeImportReviews).set({reviewHash:'b'.repeat(64)}).where(eq(schema.financeImportReviews.importId,rollbackId));
 await rejects(approveAndPostImport(db,finance,rollbackId,{confirmed:true,reviewHash:review.reviewHash,note:'Stale review'}),'REVIEW_CHANGED');
 check(await scalar(schema.journal)===before&&await scalar(schema.records)===baseline,'Stale approval leaves all business records and ledger lines untouched');
 const rollbackPrepared=await prepareImportPosting(db,finance,rollbackId,[{...decisions[0],rowId:rollbackRow.id}]);
 const auditBefore=await scalar(schema.audit),operationsBefore=await scalar(schema.operations);
 let writes=0;
 const failingDB=new Proxy(db,{get(target,key,receiver){
  if(key==='transaction')return (callback:Parameters<typeof db.transaction>[0])=>target.transaction(tx=>callback(new Proxy(tx,{get(transaction,method,context){
   if(method==='insert')return (table:Parameters<typeof tx.insert>[0])=>{if(table===schema.journal&&++writes===2)throw Error('Injected transport failure');return transaction.insert(table);};
   return Reflect.get(transaction,method,context);
  }})));
  return Reflect.get(target,key,receiver);
 }});
 await assert.rejects(approveAndPostImport(failingDB,finance,rollbackId,{confirmed:true,reviewHash:rollbackPrepared.reviewHash,note:'Test atomic write rollback'}),/Injected transport failure/);passed++;
 check(await scalar(schema.journal)===before&&await scalar(schema.records)===baseline,'A failure during journal inserts rolls back drafts, postings and audit records');
 check(await scalar(schema.audit)===auditBefore&&await scalar(schema.operations)===operationsBefore,'Journal write failure also rolls back audit and operation records');
 check((await db.select().from(schema.financeImportReviews).where(eq(schema.financeImportReviews.importId,rollbackId)))[0].status==='Prepared','Failed approval remains prepared for a controlled retry');
 state=await readFinanceState(db,owner.companies);
 check(state.journal.reduce((sum,line)=>sum+line.debit-line.credit,0)===0,'All posted journal entries remain balanced');
 check(financeSnapshot(state,'Hagadol').balances['Deferred revenue']===-700,'Existing finance snapshot reads the same journal liability');
 console.log(JSON.stringify({passed,failed:0,driver:'real libSQL and Drizzle',liveProductionTouched:false}));
}finally{client.close();}
